function validate([prices, target]) {
  if (!Array.isArray(prices) || prices.length < 1 || prices.length > 500) return 'prices needs 1 to 500 entries.';
  for (const price of prices) {
    if (typeof price !== 'string' || !/^(0|[1-9]\d{0,3})\.\d{3}$/.test(price)) return 'Each price is a string like "2.500" with exactly 3 decimals.';
    if (Number(price) > 1000) return 'Each price is at most 1000.000.';
  }
  if (!Number.isInteger(target) || target < 0 || target > 1000000) return 'target is an integer between 0 and 10^6.';
  return null;
}

