function minimizeError(prices, target) {
  let floorSum = 0;
  const fractions = [];
  for (const price of prices) {
    const [whole, part] = price.split('.');
    floorSum += Number(whole);
    const fraction = Number(part);
    if (fraction > 0) fractions.push(fraction);
  }
  const ceilCount = target - floorSum;
  if (ceilCount < 0 || ceilCount > fractions.length) return '-1';
  fractions.sort((a, b) => b - a);
  let error = 0;
  for (let i = 0; i < fractions.length; i++) {
    if (i < ceilCount) {
      error += 1000 - fractions[i];
    } else {
      error += fractions[i];
    }
  }
  const units = Math.floor(error / 1000);
  const thousandths = String(error % 1000).padStart(3, '0');
  return units + '.' + thousandths;
}

