function minimizeError(prices, target) {
  const values = prices.map(p => Math.round(parseFloat(p) * 1000));
  const n = values.length;
  let best = -1;
  for (let mask = 0; mask < (1 << n); mask++) {
    let sum = 0, error = 0;
    for (let i = 0; i < n; i++) {
      const rounded = (mask >> i) & 1 ? Math.ceil(values[i] / 1000) : Math.floor(values[i] / 1000);
      sum += rounded;
      error += Math.abs(rounded * 1000 - values[i]);
    }
    if (sum === target && (best === -1 || error < best)) best = error;
  }
  return best === -1 ? '-1' : (best / 1000).toFixed(3);
}

