function generate(rand, size) {
  const n = size === 'large' ? 500 : 1 + Math.floor(rand() * 8);
  const maxWhole = size === 'large' ? 1000 : 6;
  const specials = [0, 1, 500, 999];
  const prices = [];
  let floorSum = 0, fractional = 0;
  for (let i = 0; i < n; i++) {
    const whole = Math.floor(rand() * (maxWhole + 1));
    let fraction = rand() < 0.3 ? specials[Math.floor(rand() * specials.length)] : Math.floor(rand() * 1000);
    if (whole === 1000) fraction = 0;
    floorSum += whole;
    if (fraction > 0) fractional++;
    prices.push(whole + '.' + String(fraction).padStart(3, '0'));
  }
  const roll = rand();
  let target;
  if (roll < 0.1) target = floorSum - 1 - Math.floor(rand() * 3);
  else if (roll < 0.2) target = floorSum + fractional + 1 + Math.floor(rand() * 3);
  else target = floorSum + Math.floor(rand() * (fractional + 1));
  return [prices, Math.max(0, target)];
}
